import assert from "node:assert/strict";

function parseCurrency(price: string): number {
  if (!/^\d+(\.\d{1,2})?$/.test(price)) {
    throw new Error(`Invalid currency format: "${price}"`);
  }
  const amount = Number(price);
  return amount;
}

assert.equal(parseCurrency("42.50"), 42.5);
assert.equal(parseCurrency("0.99"), 0.99);
assert.throws(() => parseCurrency("42.50abc"));
